#!/usr/bin/env bash
#
# gen-router.sh — 从 contracts IDL 再生成 core 的 hz 路由（gen/router/）
#
# 路由治理策略（2026-10-06 起）：
#   - gen/router/ 由 hz 从 IDL 再生成，"Code generated" 文件不再手工维护；
#     gen/router/*/middleware.go（鉴权接线）是唯一手工保留区，hz update 不会触碰。
#   - gen/handler/ 的既有实现是手工业务代码：hz update 只会为"IDL 新增方法"创建
#     新桩文件，既有文件最多被追加一行 model import（本脚本统一回退该噪音）。
#   - ⚠️ 已知坑（2026-10-12）：hz 的"方法已存在"检查只看同名 service 文件，不看
#     同包其他手写文件——admin 的 10 个 handler 实现在 admin_manage.go，全量再生成
#     会在 admin_service.go 重复生成桩（redeclared 构建断）。症状=go build 报
#     "X redeclared ... other declaration"；处置=git checkout -- gen/handler/<pkg>/
#     还原被写脏的 service 文件（手写实现都在，桩是纯噪音）。
#     本脚本生成后自动检测该命中并在结尾打印确切恢复命令（只提示不自动回退；
#     IDL 新增方法的全新桩文件不受影响）。
#   - 模型不落在 core：模型真相源是 contracts（gen-model.sh 再生成到 contracts/gen/），
#     本脚本把 hz 的模型产物写进临时目录并在结束后删除。
#   - 路由守卫：bootstrap/routes_guard_test.go + ratelimit_bucket_test.go 以真实
#     注册路由为契约双向守卫，任何 IDL↔路由漂移会在 go test 时失败。
#
# 依赖: hz v0.9.7（../contracts/scripts/install-tools.sh 同款，路径相对本仓根）；
#       IDL 来自相邻的 contracts 仓
# 用法:
#   ./scripts/gen-router.sh            # 全量再生成（工作区内需有 ../contracts/idl）
#   IDL_DIR=/path/to/idl ./scripts/gen-router.sh   # 显式指定 IDL 目录
#   CHECK=1 ./scripts/gen-router.sh    # 对账模式：在临时沙箱里再生成并与现仓 gen/ 比对，
#                                      # 不落盘、不改任何仓库文件；不一致报差异退出 1
#                                      # （CI 生成物对账用，见 .github/workflows/ci.yml）
set -euo pipefail
cd "$(dirname "$0")/.."

MODULE="github.com/pigeonbox/core"
HZ_VERSION="v0.9.7"
CHECK="${CHECK:-0}"

fail() { echo -e "\033[1;31m[ERROR]\033[0m $1" >&2; exit 1; }

command -v hz >/dev/null || fail "hz 未安装: go install github.com/cloudwego/hertz/cmd/hz@${HZ_VERSION}（或跑 ../contracts/scripts/install-tools.sh hz）"

# 定位 contracts IDL（默认按工作区布局 ../contracts/idl）
IDL_SRC="${IDL_DIR:-$(pwd)/../contracts/idl}"
[ -d "$IDL_SRC" ] || fail "IDL 目录不存在: $IDL_SRC（工作区内应有相邻 contracts 仓，或 IDL_DIR=/path/to/idl）"

# hz 插件按 out_dir 相对解析 IDL，拷贝进仓内临时目录再跑
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
cp -R "$IDL_SRC" "$WORK/idl"

# CHECK=1：仓库文件一律不落盘，生成进沙箱。沙箱只快照 gen/handler——hz 的"新增
# 方法才建新桩"判定依赖既有 handler 文件，缺了会偏离真实生成行为；gen/router 不带
# 快照、由 hz 空白起始再生成，否则仓内杂散文件会被原样复制进沙箱、两边等价检不出。
# 常规模式照旧原地生成（HZ_OUT=.），行为与历史版本完全一致。
if [ "$CHECK" = "1" ]; then
  RUN_ROOT="$WORK/run"
  mkdir -p "$RUN_ROOT/gen"
  if [ -d gen/handler ]; then
    cp -R gen/handler "$RUN_ROOT/gen/handler"
  fi
  HZ_OUT="$RUN_ROOT"
else
  HZ_OUT="."
fi

# .hz 元数据（旧版 key:value 格式；routerDir 决定路由落点 gen/router）
cat > "$HZ_OUT/.hz" << EOF
// Code generated by hz. DO NOT EDIT.

hz version: ${HZ_VERSION}
handlerDir: gen/handler
modelDir: hzmodel
routerDir: gen/router
EOF

# 仅处理带 service 定义的 IDL（纯 struct 文件随 include 自动带出）
IDLS=()
for f in "$WORK"/idl/*.thrift "$WORK"/idl/http/*.thrift; do
  [ -f "$f" ] || continue
  if grep -qE '^[[:space:]]*service[[:space:]]+[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\{' "$f"; then
    IDLS+=("$f")
  fi
done
[ ${#IDLS[@]} -gt 0 ] || fail "未找到带 service 定义的 thrift IDL"

echo "==> 共 ${#IDLS[@]} 个 IDL，再生成路由（middleware.go 不受影响）..."
for f in "${IDLS[@]}"; do
  echo "  - hz update: $(basename "$f")"
  hz update --sort_router --idl "$f" --module "$MODULE" --out_dir "$HZ_OUT" \
    --handler_dir gen/handler --model_dir hzmodel -I "$WORK/idl" \
    > /dev/null
done

# 清理：模型临时目录 + handler 被追加的 hzmodel import 噪音（handler 归手工所有）
rm -rf "$HZ_OUT/hzmodel"
# 仅摘除 hz update 追加的 hzmodel import 行（模型真相源在 contracts）。
# 不可整文件 git checkout——会连带清掉未提交的手工 handler 实现
# （2026-10-09 事故：用户分享组 5 个已实现 handler 被本循环整文件回退）。
# 仅删 import 规格行(可带别名的 "…/hzmodel[/子包]" 字面量独占一行);含 hzmodel
# 字样的手写注释必须存活——旧 /hzmodel/d 全行匹配会误删(2026-10-10 IDL
# 迁移实测吞掉一句手工注释)。
# 2026-10-12 修复：正则此前只匹配 `/hzmodel/` 行尾形态，漏掉 `/hzmodel/setup`
# 等子包 import（hz 实际产物形态），16 个 handler 被留死 import 致构建断——
# 补 `(\/[^"]*)?` 子包段。
# 2026-10-15 移植性修复：`sed -i ''` 是 BSD 专有语法，GNU sed（Linux）直接报错，
# 改用 perl -ni 原地删行（macOS BSD 与 GNU/Linux 行为一致，均预装 perl）。
# 变更文件清单来源随模式而变：
#   常规模式 = git diff（仓内真实工作区改动）；
#   CHECK 模式 = 仓库未被触碰，改用沙箱 vs 仓库的 diff -rq 对账（保留沙箱绝对
#   路径，摘行动作必须落在沙箱文件上）。
if [ "$CHECK" = "1" ]; then
  CHANGED_FILES="$(diff -rq gen/handler "$RUN_ROOT/gen/handler" 2>/dev/null \
    | sed -nE 's/^Files [^ ]+ and (.*) differ$/\1/p')" || true
else
  CHANGED_FILES="$(git diff --name-only -- gen/handler)" || true
fi
printf '%s\n' "$CHANGED_FILES" | while IFS= read -r f; do
  [ -n "$f" ] || continue
  [ -f "$f" ] || continue
  if grep -q 'hzmodel' "$f"; then
    perl -ni -e 'print unless /^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*[[:space:]]+)?"[^"]*\/hzmodel(\/[^"]*)?"[[:space:]]*$/' "$f"
  fi
done

# ============ CHECK=1：对账裁决 ============
# gen/router 逐字节严格比对（路由是 IDL 的直接投影，任何差异=漂移）；沙箱是空白
# 起始再生成，内容 diff + 文件清单对账能同时抓"被手改/未同步"与"多出/缺失的文件"。
# gen/handler 只对账文件增删（IDL 新增/删除方法的桩，缺失=IDL 改了没同步生成物）。
if [ "$CHECK" = "1" ]; then
  # 手工区文件不在 hz update 产物范围（沙箱 router 空白起始没有它们），按名字白名单
  # 回填后再对账：*/middleware.go（鉴权接线）与根 register.go（customizedRegister
  # 白名单，头部虽带 generated 标记但由手工维护）。其余沙箱缺失的文件=IDL 已删除的
  # 陈旧生成物，不回填、留给下方对账报差异。
  (cd gen/router && find . -type f \( -name 'middleware.go' -o -path './register.go' \)) | while IFS= read -r mf; do
    mkdir -p "$RUN_ROOT/gen/router/$(dirname "$mf")"
    cp "gen/router/$mf" "$RUN_ROOT/gen/router/$mf"
  done
  ROUTER_DIFF="$(diff -r "$RUN_ROOT/gen/router" gen/router)" || true
  # 文件清单另对账：内容 diff 对"仓内多出来的杂散文件"是盲的，清单比对才抓得住
  LIST_DIFF="$(diff <(cd gen/handler && find . -type f | sort) \
                    <(cd "$RUN_ROOT/gen/handler" && find . -type f | sort))" || true
  ROUTER_LIST_DIFF="$(diff <(cd gen/router && find . -type f | sort) \
                     <(cd "$RUN_ROOT/gen/router" && find . -type f | sort))" || true
  if [ -n "$ROUTER_DIFF" ] || [ -n "$LIST_DIFF" ] || [ -n "$ROUTER_LIST_DIFF" ]; then
    {
      echo -e "\033[1;31m[ERROR]\033[0m CHECK 失败：仓内生成物与 IDL 再生成结果不一致（IDL 改了没跑 gen-router.sh，或生成物被手改）"
      if [ -n "$ROUTER_DIFF" ]; then
        echo "--- gen/router/ 差异（前 40 行，全量: diff -r <沙箱> gen/router）---"
        printf '%s\n' "$ROUTER_DIFF" | head -40
      fi
      if [ -n "$LIST_DIFF" ]; then
        echo "--- gen/handler/ 文件增删 ---"
        printf '%s\n' "$LIST_DIFF" | head -20
      fi
      if [ -n "$ROUTER_LIST_DIFF" ]; then
        echo "--- gen/router/ 文件增删（含杂散文件）---"
        printf '%s\n' "$ROUTER_LIST_DIFF" | head -20
      fi
      echo "同步: ./scripts/gen-router.sh（IDL 变更先走 contracts 生成链）"
    } >&2
    exit 1
  fi
  # 既有 handler 文件的内容差异 = 上述确定性桩追加坑（每次全量生成必然出现，
  # 非漂移），只提示不判失败——与常规模式的提示口径一致。
  REGEN_DIRTY="$(diff -rq gen/handler "$RUN_ROOT/gen/handler" 2>/dev/null \
    | sed -nE 's/^Files [^ ]+ and (.*) differ$/\1/p' | sed "s|^$RUN_ROOT/||")" || true
  if [ -n "$REGEN_DIRTY" ]; then
    echo -e "\033[1;33m⚠ 已知坑：hz 会向以下既有 handler 文件追加重复桩（redeclared 噪音，非漂移）\033[0m"
    printf '%s\n' "$REGEN_DIRTY" | sed 's/^/    /'
    echo "若用常规模式跑生成，结束后还原这些文件（桩是纯噪音，手写实现都在同包其他文件）："
    echo "    git checkout -- $(printf '%s\n' "$REGEN_DIRTY" | tr '\n' ' ')"
  fi
  echo "✓ CHECK=1 通过：gen/ 与 IDL 再生成结果一致（本次未改动任何仓库文件）"
  exit 0
fi

# ============ 常规模式收尾 ============
# 已知坑的运行时自救（知识原先只在头注释里，撞上 "X redeclared" 的人看不到）：
# 检测被 hz 改写的既有 handler 文件（git status 排除 ?? 未跟踪——全新桩文件是
# IDL 新增方法的预期产物，不应回退），打印醒目提示 + 确切恢复命令。只提示不自动回退。
DIRTY_HANDLER="$(git status --porcelain -- gen/handler | grep -v '^??' || true)"
NEW_STUBS="$(git status --porcelain -- gen/handler | grep '^??' || true)"
if [ -n "$DIRTY_HANDLER" ]; then
  DIRTY_LIST="$(printf '%s\n' "$DIRTY_HANDLER" | cut -c4-)"
  echo ""
  echo -e "\033[1;33m⚠ 已知坑命中：hz 向既有 handler 文件追加了重复桩，go build 将报 \"X redeclared ... other declaration\"\033[0m"
  printf '%s\n' "$DIRTY_LIST" | sed 's/^/    被改写: /'
  echo "恢复（只还原被改写的文件；IDL 新增方法的全新桩文件保留）："
  echo "    git checkout -- $(printf '%s\n' "$DIRTY_LIST" | tr '\n' ' ')"
fi
if [ -n "$NEW_STUBS" ]; then
  echo ""
  echo "ℹ 新增桩文件（IDL 新增方法的预期产物，保留即可）："
  printf '%s\n' "$NEW_STUBS" | cut -c4- | sed 's/^/    /'
fi

echo "✓ 已再生成 gen/router/。自检："
echo "  git diff gen/router/   # 应仅排序/嵌套风格或真实 IDL 变更；middleware.go 不应出现"
echo "  go test ./bootstrap/   # 路由守卫（TestRegisteredRoutesMatchContract 等）必须绿"
